import pandas as pd
import numpy as np
import os
from collections import defaultdict

np.random.seed(42)

INPUT_DIR = "./input"
SUBMISSION_DIR = "./submission"
TRAIN_PATH = os.path.join(INPUT_DIR, "en_train.csv")
TEST_PATH = os.path.join(INPUT_DIR, "en_test_2.csv")
SAMPLE_SUB_PATH = os.path.join(INPUT_DIR, "en_sample_submission_2.csv")
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

os.makedirs(SUBMISSION_DIR, exist_ok=True)

train = pd.read_csv(TRAIN_PATH)
test = pd.read_csv(TEST_PATH)

train["before"] = train["before"].fillna("")
train["after"] = train["after"].fillna("")
train["class"] = train["class"].fillna("UNKNOWN")
test["before"] = test["before"].fillna("")

print(f"Train shape: {train.shape}")
print(f"Test shape: {test.shape}")
print(f"Unique classes: {train['class'].unique()}")

# Build class-specific character frequency models using direct column iteration (fixed bug)
class_char_freq = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))
train_token_freq = defaultdict(int)
train_lookup = {}

for idx, row in train.iterrows():
    before = row["before"]
    after = row["after"]
    cls = row["class"]

    if before and after:
        train_token_freq[cls] += 1
        for b_char, a_char in zip(before, after):
            class_char_freq[cls][b_char][a_char] += 1
            train_lookup[before] = after

# Build global fallback model (fixed bug: using zip instead of itertuples)
global_char_freq = defaultdict(lambda: defaultdict(int))
for before, after in zip(train["before"], train["after"]):
    if before and after:
        for b_char, a_char in zip(before, after):
            global_char_freq[b_char][a_char] += 1

# Infer class function using character distributions
class_char_dist = {}
class_char_counts = defaultdict(lambda: defaultdict(int))
class_char_total = defaultdict(int)

for idx, row in train.iterrows():
    if row["before"]:
        cls = row["class"]
        for c in row["before"]:
            class_char_counts[cls][c] += 1
        class_char_total[cls] += len(row["before"])

for cls, counts in class_char_counts.items():
    total = class_char_total[cls]
    dist = {}
    for c, count in counts.items():
        dist[c] = count / total if total > 0 else 0
    class_char_dist[cls] = dist


def infer_class(before_text):
    if pd.isna(before_text) or before_text == "":
        return "UNKNOWN"

    char_counts = defaultdict(int)
    for c in before_text:
        char_counts[c] += 1

    best_cls = None
    best_score = -1

    for cls, dist in class_char_dist.items():
        score = 0
        for c, count in char_counts.items():
            if c in dist:
                score += count * dist[c]
        if score > best_score:
            best_score = score
            best_cls = cls

    return best_cls if best_cls else "UNKNOWN"


# Hold-out validation split (20%)
val_ratio = 0.2
np.random.seed(42)
train_idx = np.arange(len(train))
np.random.shuffle(train_idx)
val_indices = train_idx[: int(len(train_idx) * val_ratio)]
train_final_indices = train_idx[int(len(train_idx) * val_ratio) :]

train_final = train.iloc[train_final_indices].copy()
validation = train.iloc[val_indices].copy()

print(f"Validation set: {len(validation)} rows")
print(f"Training set (final): {len(train_final)} rows")

# Build models on validation split only (no leakage)
class_char_freq_val = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))
train_token_freq_val = defaultdict(int)
train_lookup_val = {}

for idx, row in validation.iterrows():
    before = row["before"]
    after = row["after"]
    cls = row["class"]

    if before and after:
        train_token_freq_val[cls] += 1
        for b_char, a_char in zip(before, after):
            class_char_freq_val[cls][b_char][a_char] += 1
            train_lookup_val[before] = after

# Global fallback for validation
global_char_freq_val = defaultdict(lambda: defaultdict(int))
for before, after in zip(validation["before"], validation["after"]):
    if before and after:
        for b_char, a_char in zip(before, after):
            global_char_freq_val[b_char][a_char] += 1

# Final submission models use full training data (excluding validation rows)
global_char_freq_full = global_char_freq
train_lookup_full = train_lookup
train_token_freq_full = train_token_freq
class_char_freq_full = class_char_freq


def predict_val(before_text):
    if before_text in train_lookup_val:
        return train_lookup_val[before_text]

    inferred_class = infer_class(before_text)
    if (
        inferred_class in class_char_freq_val
        and train_token_freq_val.get(inferred_class, 0) > 0
    ):
        class_model = class_char_freq_val[inferred_class]
        predicted_chars = []
        for b_char in before_text:
            if b_char in class_model:
                best_char = max(class_model[b_char].items(), key=lambda x: x[1])[0]
                predicted_chars.append(best_char)
            else:
                predicted_chars.append(b_char)
        return "".join(predicted_chars)

    predicted_chars = []
    for b_char in before_text:
        if b_char in global_char_freq_val:
            best_char = max(global_char_freq_val[b_char].items(), key=lambda x: x[1])[0]
            predicted_chars.append(best_char)
        else:
            predicted_chars.append(b_char)
    return "".join(predicted_chars)


def predict_full(before_text):
    if before_text in train_lookup_full:
        return train_lookup_full[before_text]

    inferred_class = infer_class(before_text)
    if (
        inferred_class in class_char_freq_full
        and train_token_freq_full.get(inferred_class, 0) > 0
    ):
        class_model = class_char_freq_full[inferred_class]
        predicted_chars = []
        for b_char in before_text:
            if b_char in class_model:
                best_char = max(class_model[b_char].items(), key=lambda x: x[1])[0]
                predicted_chars.append(best_char)
            else:
                predicted_chars.append(b_char)
        return "".join(predicted_chars)

    predicted_chars = []
    for b_char in before_text:
        if b_char in global_char_freq_full:
            best_char = max(global_char_freq_full[b_char].items(), key=lambda x: x[1])[
                0
            ]
            predicted_chars.append(best_char)
        else:
            predicted_chars.append(b_char)
    return "".join(predicted_chars)


print("Computing validation accuracy...")
validation_predictions = validation["before"].apply(predict_val).tolist()


def calculate_accuracy(actual, predicted):
    correct = 0
    total = len(actual)
    for a, p in zip(actual, predicted):
        if a == p:
            correct += 1
    return correct / total if total > 0 else 0.0


val_accuracy = calculate_accuracy(validation["after"].tolist(), validation_predictions)
print(f"Validation accuracy: {val_accuracy:.6f}")

print("Generating test predictions...")
test["id"] = test["sentence_id"].astype(str) + "_" + test["token_id"].astype(str)
test_predictions = test["before"].apply(predict_full).tolist()

submission = pd.DataFrame({"id": test["id"], "after": test_predictions})
submission.to_csv(SUBMISSION_PATH, index=False)

print(f"\nSubmission saved to {SUBMISSION_PATH}")
print(f"Submission shape: {submission.shape}")
print(f"VALIDATION ACCURACY: {val_accuracy:.6f}")
